def f(N: int, M: int, triples: List[Tuple[int, int, int]], Q: int, pairs: List[Tuple[int, int]]) -> int:
    from collections import defaultdict

    # Store counts of each number in the first and second element of the triples
    count = defaultdict(int)
    for a, b, c in triples:
        count[a] += 1
        count[b] += 1

    # Initialize a list to store the result
    result = [0] * N

    # For each pair (d, e), if d or e is in the count, add e to the corresponding result
    for d, e in pairs:
        if d in count:
            result[d - 1] += e
        if e in count:
            result[e - 1] += d

    # Return the maximum value in the result
    return max(result)
